GlobalRankingWindowProfile GlobalAggregateWindowProfileV1(
    const api::TypedRelationalDag& dag,
    const std::uint32_t relation_node_id) {
  const api::RelationalWindowInvocationRecord* exact_invocation = nullptr;
  for (const auto& invocation : dag.window_invocations) {
    if (invocation.relation_node_id != relation_node_id) continue;
    if (exact_invocation != nullptr) return {};
    exact_invocation = &invocation;
  }
  if (exact_invocation == nullptr) return {};
  const auto* row = exec::LookupCanonicalAggregateByUuidV1(
      exact_invocation->function_uuid);
  if (row == nullptr || !row->executable || !row->aggregate_as_window ||
      row->abi_version != exact_invocation->function_abi_version ||
      row->builtin_id != exact_invocation->builtin_id) {
    return {};
  }
  std::string_view display_name;
  std::string_view result_type_name = "int64";
  switch (row->function) {
    case exec::CanonicalAggregateFunction::sum:
      display_name = "SUM";
      break;
    case exec::CanonicalAggregateFunction::min:
      display_name = "MIN";
      break;
    case exec::CanonicalAggregateFunction::max:
      display_name = "MAX";
      break;
    case exec::CanonicalAggregateFunction::count:
      display_name = "COUNT";
      break;
    case exec::CanonicalAggregateFunction::bool_and:
      display_name = "BOOL_AND";
      result_type_name = "boolean";
      break;
    case exec::CanonicalAggregateFunction::bool_or:
      display_name = "BOOL_OR";
      result_type_name = "boolean";
      break;
    case exec::CanonicalAggregateFunction::every:
      display_name = "EVERY";
      result_type_name = "boolean";
      break;
    default:
      return {};
  }
  return {"window.aggregate-bridge.v1", row->builtin_id,
          row->function_uuid, display_name, result_type_name};
}
constexpr std::uint64_t kRealRankingRatioTextMaximumBytes = 36;
constexpr std::uint64_t kRealRankingConversionWorkspaceMaximumBytes =
    2 * kRealRankingRatioTextMaximumBytes;

// The optional Project-root form preserves a narrower public SELECT list and
// additionally binds every Window passthrough to its ordered input expression.
PreparedGlobalRowNumberWindowBinding PrepareGlobalRankingWindowBinding(
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalPropertyCatalog& logical_properties,
    const api::RelationalDagNode& consumer,
    const plan::CanonicalLogicalRelationalNode& logical_consumer,
    const plan::CanonicalLogicalRelationalNode& previous_logical,
    const PreparedSortRoot& prepared_sort,
    const std::size_t materialized_column_count,
    const std::size_t result_binding_count,
    const std::string& result_type_uuid,
    const std::string& order_type_uuid,
    const std::string& boolean_type_uuid,
    const std::array<std::string, 4>& bounded_signed_type_uuids,
    const std::string_view family_label,
    const GlobalRankingWindowProfile& profile,
    const bool allow_project_root = false) {
  PreparedGlobalRowNumberWindowBinding result;
  result.detail = std::string(family_label) + " " +
                  std::string(profile.display_name) +
                  " binding is not exact";

  std::vector<const api::RelationalWindowDefinitionRecord*> definitions;
  std::vector<const api::RelationalWindowInvocationRecord*> invocations;
  for (const auto& definition : dag.window_definitions) {
    if (definition.relation_node_id == consumer.node_id) {
      definitions.push_back(&definition);
    }
  }
  for (const auto& invocation : dag.window_invocations) {
    if (invocation.relation_node_id == consumer.node_id) {
      invocations.push_back(&invocation);
    }
  }
  for (const auto& output : dag.outputs) {
    if (output.relation_node_id == consumer.node_id) {
      result.outputs.push_back(&output);
    }
  }
  std::ranges::sort(result.outputs, {},
                    &api::RelationalOutputRecord::ordinal);
  const auto typed_root = std::ranges::find_if(
      dag.nodes, [&](const auto& node) {
        return node.node_id == dag.root_node_id;
      });
  const bool exact_window_position =
      consumer.node_id == dag.root_node_id ||
      (allow_project_root && typed_root != dag.nodes.end() &&
       typed_root->node_kind == api::RelationalDagNodeKind::kProject &&
       typed_root->input_node_ids ==
           std::vector<std::uint32_t>{consumer.node_id});

  const auto typed_sort = std::ranges::find_if(
      dag.nodes, [&](const auto& node) {
        return node.node_id == previous_logical.logical_node_id;
      });
  const auto typed_order_expression =
      typed_sort != dag.nodes.end() &&
              typed_sort->bound_expression_ids.size() == 1
          ? std::ranges::find_if(dag.expressions, [&](const auto& expression) {
              return expression.expression_id ==
                     typed_sort->bound_expression_ids.front();
            })
          : dag.expressions.end();
  const auto typed_order_descriptor =
      typed_order_expression == dag.expressions.end()
          ? dag.descriptors.end()
          : std::ranges::find_if(dag.descriptors, [&](const auto& descriptor) {
              return descriptor.descriptor_id ==
                     typed_order_expression->result_descriptor_id;
            });
  const auto function =
      invocations.size() == 1
          ? std::ranges::find_if(dag.expressions, [&](const auto& expression) {
              return expression.expression_id ==
                     invocations.front()->function_expression_id;
            })
          : dag.expressions.end();
  const auto result_descriptor =
      invocations.size() == 1
          ? std::ranges::find_if(dag.descriptors, [&](const auto& descriptor) {
              return descriptor.descriptor_id ==
                     invocations.front()->result_descriptor_id;
            })
          : dag.descriptors.end();
  const bool ntile_window = profile.builtin_id == "sb.window.ntile";
  const bool lag_window = profile.builtin_id == "sb.window.lag";
  const bool lead_window = profile.builtin_id == "sb.window.lead";
  const bool navigation_window = lag_window || lead_window;
  const bool first_value_window =
      profile.builtin_id == "sb.window.first_value";
  const bool last_value_window =
      profile.builtin_id == "sb.window.last_value";
  const bool nth_value_window =
      profile.builtin_id == "sb.window.nth_value";
  const bool navigation_value_window =
      navigation_window || first_value_window || last_value_window ||
      nth_value_window;
  const bool aggregate_window =
      profile.semantic_variant_id == "window.aggregate-bridge.v1";
  const bool aggregate_count_window =
      aggregate_window && profile.builtin_id == "sb.aggregate.count";
  const bool aggregate_boolean_window =
      aggregate_window &&
      (profile.builtin_id == "sb.aggregate.bool_and" ||
       profile.builtin_id == "sb.aggregate.bool_or" ||
       profile.builtin_id == "sb.aggregate.every");
  const bool aggregate_bounded_signed_window =
      aggregate_window && !aggregate_count_window &&
      !aggregate_boolean_window;
  const bool fixed_unqualified_ranking_result_window =
      profile.builtin_id == "sb.window.row_number" ||
      profile.builtin_id == "sb.window.rank" ||
      profile.builtin_id == "sb.window.dense_rank" ||
      profile.builtin_id == "sb.window.percent_rank" ||
      profile.builtin_id == "sb.window.cume_dist" ||
      profile.builtin_id == "sb.window.ntile";
  const bool aggregate_count_star_window =
      aggregate_count_window && invocations.size() == 1 &&
      invocations.front()->argument_expression_ids.empty();
  const bool value_window =
      navigation_window || first_value_window || last_value_window ||
      nth_value_window || aggregate_window;
  const bool value_operand_window =
      value_window && !aggregate_count_star_window;
  const bool exact_argument_arity =
      invocations.size() == 1 &&
      (nth_value_window
           ? invocations.front()->argument_expression_ids.size() == 2
           : aggregate_count_star_window
           ? invocations.front()->argument_expression_ids.empty()
           : ((ntile_window || value_operand_window)
                  ? invocations.front()->argument_expression_ids.size() == 1
                  : invocations.front()->argument_expression_ids.empty()));
  std::vector<std::uint32_t> expected_bound_expression_ids;
  if (typed_sort != dag.nodes.end() &&
      typed_sort->bound_expression_ids.size() == 1 &&
      invocations.size() == 1 && exact_argument_arity) {
    expected_bound_expression_ids.push_back(
        typed_sort->bound_expression_ids.front());
    expected_bound_expression_ids.insert(
        expected_bound_expression_ids.end(),
        invocations.front()->argument_expression_ids.begin(),
        invocations.front()->argument_expression_ids.end());
    expected_bound_expression_ids.push_back(
        invocations.front()->function_expression_id);
  }
  std::uint32_t input_lineage_node_id = 0;
  bool input_lineage_exact = !allow_project_root;
  if (allow_project_root) {
    input_lineage_exact =
        typed_sort != dag.nodes.end() &&
        typed_sort->input_node_ids.size() == 1;
  }
  if (allow_project_root && input_lineage_exact) {
    input_lineage_node_id = typed_sort->input_node_ids.front();
    std::unordered_set<std::uint32_t> lineage_visited;
    while (input_lineage_exact &&
           std::ranges::none_of(dag.outputs, [&](const auto& output) {
             return output.relation_node_id == input_lineage_node_id;
           })) {
      if (!lineage_visited.insert(input_lineage_node_id).second) {
        input_lineage_exact = false;
        break;
      }
      const auto lineage_node = std::ranges::find_if(
          dag.nodes, [&](const auto& node) {
            return node.node_id == input_lineage_node_id;
          });
      if (lineage_node == dag.nodes.end() ||
          (lineage_node->node_kind != api::RelationalDagNodeKind::kFilter &&
           lineage_node->node_kind != api::RelationalDagNodeKind::kSort) ||
          lineage_node->input_node_ids.size() != 1) {
        input_lineage_exact = false;
        break;
      }
      const auto lineage_input = std::ranges::find_if(
          dag.nodes, [&](const auto& node) {
            return node.node_id == lineage_node->input_node_ids.front();
          });
      if (lineage_input == dag.nodes.end() ||
          lineage_node->output_descriptor_ids !=
              lineage_input->output_descriptor_ids) {
        input_lineage_exact = false;
        break;
      }
      input_lineage_node_id = lineage_input->node_id;
    }
  }
  std::vector<const api::RelationalOutputRecord*> input_outputs;
  for (const auto& output : dag.outputs) {
    if (input_lineage_exact &&
        output.relation_node_id == input_lineage_node_id) {
      input_outputs.push_back(&output);
    }
  }
  std::ranges::sort(input_outputs, {},
                    &api::RelationalOutputRecord::ordinal);
  const bool ordered_input =
      previous_logical.node_kind ==
          plan::CanonicalLogicalRelationalNodeKind::kSort &&
      typed_sort != dag.nodes.end() &&
      typed_sort->bound_expression_ids.size() == 1 &&
      consumer.required_property_uuids ==
          std::vector<std::string>{prepared_sort.ordering_property_uuid} &&
      consumer.delivered_property_uuids.size() == 2 &&
      std::ranges::find(consumer.delivered_property_uuids,
                        prepared_sort.ordering_property_uuid) !=
          consumer.delivered_property_uuids.end();
  bool passthrough_outputs =
      result.outputs.size() ==
          previous_logical.output_descriptor_ids.size() + 1 &&
      (!allow_project_root ||
       (input_lineage_exact &&
        input_outputs.size() ==
            previous_logical.output_descriptor_ids.size())) &&
      materialized_column_count ==
          previous_logical.output_descriptor_ids.size() &&
      result_binding_count == previous_logical.output_descriptor_ids.size();
  for (std::size_t ordinal = 0;
       passthrough_outputs &&
       ordinal < previous_logical.output_descriptor_ids.size();
       ++ordinal) {
    passthrough_outputs =
        (!allow_project_root ||
         (input_outputs[ordinal]->ordinal == ordinal &&
          input_outputs[ordinal]->descriptor_id ==
              previous_logical.output_descriptor_ids[ordinal] &&
          result.outputs[ordinal]->expression_id ==
              input_outputs[ordinal]->expression_id)) &&
        result.outputs[ordinal]->ordinal == ordinal &&
        result.outputs[ordinal]->visible &&
        result.outputs[ordinal]->descriptor_id ==
            previous_logical.output_descriptor_ids[ordinal];
  }

  if (consumer.semantic_variant_id != profile.semantic_variant_id ||
      !exact_window_position ||
      consumer.input_node_ids !=
          std::vector<std::uint32_t>{previous_logical.logical_node_id} ||
      logical_consumer.input_logical_node_ids !=
          std::vector<std::uint32_t>{previous_logical.logical_node_id} ||
      !ordered_input ||
      definitions.size() != 1 || invocations.size() != 1 ||
      !exact_argument_arity || !passthrough_outputs ||
      !consumer.required_object_uuids.empty() ||
      consumer.bound_expression_ids != expected_bound_expression_ids ||
      definitions.front()->canonical_name_key.has_value() ||
      definitions.front()->inherited_window_id.has_value() ||
      !definitions.front()->partition_expression_ids.empty() ||
      definitions.front()->ordering_terms.size() != 1 ||
      definitions.front()->ordering_terms.front().expression_id !=
          typed_sort->bound_expression_ids.front() ||
      definitions.front()->frame_unit.has_value() ||
      definitions.front()->frame_start.has_value() ||
      definitions.front()->frame_end.has_value() ||
      definitions.front()->exclusion !=
          api::RelationalWindowFrameExclusion::kNoOthers ||
      invocations.front()->window_definition_id !=
          definitions.front()->window_id ||
      invocations.front()->function_abi_version != 1 ||
      invocations.front()->builtin_id != profile.builtin_id ||
      invocations.front()->function_uuid != profile.function_uuid ||
      function == dag.expressions.end() ||
      function->expression_kind !=
          api::RelationalExpressionKind::kFunctionCall ||
      function->function_uuid !=
          std::optional<std::string>(profile.function_uuid) ||
      function->bound_name_uuid.has_value() ||
      function->operator_name.has_value() ||
      function->literal_kind.has_value() ||
      function->literal_or_parameter_ref.has_value() ||
      function->child_expression_ids !=
          invocations.front()->argument_expression_ids ||
      function->result_descriptor_id !=
          invocations.front()->result_descriptor_id ||
      result_descriptor == dag.descriptors.end() || result_type_uuid.empty() ||
      result_descriptor->type_uuid != result_type_uuid ||
      result_descriptor->nullability !=
          (value_window && !aggregate_count_window
               ? api::RelationalNullability::kNullable
               : api::RelationalNullability::kNonNull) ||
      ((aggregate_window || fixed_unqualified_ranking_result_window) &&
       (result_descriptor->collation_uuid.has_value() ||
        result_descriptor->timezone_profile_id.has_value() ||
        result_descriptor->width.has_value() ||
        result_descriptor->precision.has_value() ||
        result_descriptor->scale.has_value())) ||
      consumer.output_descriptor_ids.size() !=
          previous_logical.output_descriptor_ids.size() + 1 ||
      !std::equal(previous_logical.output_descriptor_ids.begin(),
                  previous_logical.output_descriptor_ids.end(),
                  consumer.output_descriptor_ids.begin()) ||
      consumer.output_descriptor_ids.back() !=
          result_descriptor->descriptor_id ||
      logical_consumer.output_descriptor_ids !=
          consumer.output_descriptor_ids ||
      result.outputs.back()->ordinal !=
          previous_logical.output_descriptor_ids.size() ||
      !result.outputs.back()->visible ||
      result.outputs.back()->expression_id != function->expression_id ||
      result.outputs.back()->descriptor_id !=
          result_descriptor->descriptor_id ||
      result.outputs.back()->output_name_utf8 !=
          invocations.front()->output_name_utf8) {
    return result;
  }

  const auto window_property_uuid = std::ranges::find_if(
      consumer.delivered_property_uuids, [&](const auto& property_uuid) {
        return property_uuid != prepared_sort.ordering_property_uuid;
      });
  const auto window_property = std::ranges::find_if(
      logical_properties.properties, [&](const auto& property) {
        return window_property_uuid != consumer.delivered_property_uuids.end() &&
               property.property_uuid == *window_property_uuid;
      });
  if (window_property_uuid == consumer.delivered_property_uuids.end() ||
      window_property == logical_properties.properties.end() ||
      window_property->property_kind !=
          plan::CanonicalLogicalPropertyKind::kWindow ||
      window_property->origin_logical_node_id != consumer.node_id ||
      window_property->dependency_property_uuids !=
          std::vector<std::string>{prepared_sort.ordering_property_uuid} ||
      window_property->window_frame_descriptor_uuid.empty()) {
    result.diagnostic_id = "QOW-DIAG-WINDOW-PROPERTY-CARRIAGE-V1";
    result.detail = std::string(family_label) + " " +
                    std::string(profile.display_name) +
                    " property binding is not exact";
    return result;
  }
  if (fixed_unqualified_ranking_result_window) {
    const std::array<std::string_view, 6> ranking_identity_domain{
        result_descriptor->descriptor_uuid,
        result_type_uuid,
        profile.function_uuid,
        prepared_sort.ordering_property_uuid,
        *window_property_uuid,
        window_property->window_frame_descriptor_uuid};
    const std::unordered_set<std::string_view> distinct_ranking_identities(
        ranking_identity_domain.begin(), ranking_identity_domain.end());
    if (distinct_ranking_identities.size() != ranking_identity_domain.size() ||
        std::ranges::any_of(ranking_identity_domain, [](const auto identity) {
          return !CanonicalUuidText(identity);
        })) {
      result.detail = std::string(family_label) + " " +
                      std::string(profile.display_name) +
                      " result identity domain is not independent";
      return result;
    }
  }
  if (aggregate_window &&
      (result_descriptor->descriptor_uuid == result_type_uuid ||
       result_descriptor->descriptor_uuid == profile.function_uuid ||
       result_descriptor->descriptor_uuid ==
           prepared_sort.ordering_property_uuid ||
       result_descriptor->descriptor_uuid == *window_property_uuid ||
       result_descriptor->descriptor_uuid ==
           window_property->window_frame_descriptor_uuid)) {
    result.detail = std::string(family_label) + " " +
                    std::string(profile.display_name) +
                    " result descriptor identity is not independent";
    return result;
  }

  if (ntile_window) {
    const auto argument_expression_id =
        invocations.front()->argument_expression_ids.front();
    const auto argument = std::ranges::find_if(
        dag.expressions, [&](const auto& expression) {
          return expression.expression_id == argument_expression_id;
        });
    const auto argument_descriptor = std::ranges::find_if(
        dag.descriptors, [&](const auto& descriptor) {
          return argument != dag.expressions.end() &&
                 descriptor.descriptor_id == argument->result_descriptor_id;
        });
    if (argument == dag.expressions.end() ||
        argument->expression_kind != api::RelationalExpressionKind::kLiteral ||
        !argument->child_expression_ids.empty() ||
        argument->bound_name_uuid.has_value() ||
        argument->function_uuid.has_value() ||
        argument->literal_kind != api::RelationalLiteralKind::kNumeric ||
        argument->operator_name.has_value() ||
        !argument->literal_or_parameter_ref.has_value() ||
        argument_descriptor == dag.descriptors.end() ||
        argument_descriptor->descriptor_id ==
            result_descriptor->descriptor_id ||
        argument_descriptor->descriptor_uuid ==
            result_descriptor->descriptor_uuid ||
        argument_descriptor->descriptor_uuid == profile.function_uuid ||
        argument_descriptor->descriptor_uuid ==
            prepared_sort.ordering_property_uuid ||
        argument_descriptor->descriptor_uuid == *window_property_uuid ||
        argument_descriptor->type_uuid != result_type_uuid ||
        argument_descriptor->nullability !=
            api::RelationalNullability::kNonNull ||
        argument_descriptor->collation_uuid.has_value() ||
        argument_descriptor->timezone_profile_id.has_value() ||
        argument_descriptor->width.has_value() ||
        argument_descriptor->precision.has_value() ||
        argument_descriptor->scale.has_value()) {
      result.detail = std::string(family_label) +
                      " NTILE bucket count is not one independent non-NULL "
                      "canonical int64 literal";
      return result;
    }
    CanonicalRelationalExpressionRuntime runtime(dag);
    api::EngineTypedValue operand;
    std::string operand_detail;
    if (!runtime.EvaluateForConsumer(
            argument_expression_id, "int64",
            api::EngineCanonicalExpressionConsumer::window, &operand,
            &operand_detail) ||
        operand.state != api::EngineValueState::value || operand.is_null ||
        !operand.binary_value.empty() ||
        operand.descriptor.canonical_type_name != "int64" ||
        !api::QowCanonicalDescriptorIdentityV1(operand.descriptor) ||
        operand.descriptor.descriptor_uuid.canonical !=
            argument_descriptor->descriptor_uuid) {
      result.detail = std::string(family_label) +
                      " NTILE bucket count materialization failed";
      if (!operand_detail.empty()) result.detail += ": " + operand_detail;
      return result;
    }
    const auto decoded = exec::DecodeInt64Value(operand);
    if (!decoded.ok() || decoded.value <= 0) {
      result.detail = std::string(family_label) +
                      " NTILE bucket count must be positive int64";
      return result;
    }
    result.ntile_bucket_count_operand = std::move(operand);
  } else if (value_operand_window) {
    const auto argument_expression_id =
        invocations.front()->argument_expression_ids.front();
    const auto argument = std::ranges::find_if(
        dag.expressions, [&](const auto& expression) {
          return expression.expression_id == argument_expression_id;
        });
    const auto argument_descriptor = std::ranges::find_if(
        dag.descriptors, [&](const auto& descriptor) {
          return argument != dag.expressions.end() &&
                 descriptor.descriptor_id == argument->result_descriptor_id;
        });
    const auto value_column =
        argument_descriptor == dag.descriptors.end()
            ? previous_logical.output_descriptor_ids.end()
            : std::ranges::find(previous_logical.output_descriptor_ids,
                                argument_descriptor->descriptor_id);
    const bool exact_aggregate_argument_type =
        argument_descriptor != dag.descriptors.end() &&
        (!aggregate_window || aggregate_count_window ||
         (aggregate_bounded_signed_window &&
          std::ranges::find(bounded_signed_type_uuids,
                            argument_descriptor->type_uuid) !=
              bounded_signed_type_uuids.end()) ||
         (aggregate_boolean_window && !boolean_type_uuid.empty() &&
          argument_descriptor->type_uuid == boolean_type_uuid));
    if (argument == dag.expressions.end() ||
        argument->expression_kind !=
            api::RelationalExpressionKind::kIdentifier ||
        !argument->child_expression_ids.empty() ||
        !argument->bound_name_uuid.has_value() ||
        argument->function_uuid.has_value() ||
        argument->literal_kind.has_value() ||
        argument->literal_or_parameter_ref.has_value() ||
        argument->operator_name.has_value() ||
        argument_descriptor == dag.descriptors.end() ||
        value_column == previous_logical.output_descriptor_ids.end() ||
        argument_descriptor->descriptor_id ==
            result_descriptor->descriptor_id ||
        argument_descriptor->descriptor_uuid ==
            result_descriptor->descriptor_uuid ||
        argument_descriptor->descriptor_uuid == profile.function_uuid ||
        (aggregate_window &&
         (!exact_aggregate_argument_type ||
          (!aggregate_count_window &&
           (argument_descriptor->collation_uuid.has_value() ||
            argument_descriptor->timezone_profile_id.has_value() ||
            argument_descriptor->width.has_value() ||
            argument_descriptor->precision.has_value() ||
            argument_descriptor->scale.has_value())) ||
          result_descriptor->collation_uuid.has_value() ||
          result_descriptor->timezone_profile_id.has_value() ||
          result_descriptor->width.has_value() ||
          result_descriptor->precision.has_value() ||
          result_descriptor->scale.has_value())) ||
        (!aggregate_window &&
         (argument_descriptor->type_uuid != result_type_uuid ||
          (argument_descriptor->type_uuid != order_type_uuid &&
           (!navigation_value_window || boolean_type_uuid.empty() ||
            argument_descriptor->type_uuid != boolean_type_uuid)) ||
          result_descriptor->type_uuid != argument_descriptor->type_uuid ||
          argument_descriptor->collation_uuid.has_value() ||
          argument_descriptor->timezone_profile_id.has_value() ||
          argument_descriptor->width.has_value() ||
          argument_descriptor->precision.has_value() ||
          argument_descriptor->scale.has_value() ||
          result_descriptor->collation_uuid.has_value() ||
          result_descriptor->timezone_profile_id.has_value() ||
          result_descriptor->width.has_value() ||
          result_descriptor->precision.has_value() ||
          result_descriptor->scale.has_value() ||
          result_descriptor->collation_uuid !=
              argument_descriptor->collation_uuid ||
          result_descriptor->timezone_profile_id !=
              argument_descriptor->timezone_profile_id ||
          result_descriptor->width != argument_descriptor->width ||
          result_descriptor->precision != argument_descriptor->precision ||
          result_descriptor->scale != argument_descriptor->scale))) {
      result.detail = std::string(family_label) +
                      " " + std::string(profile.display_name) +
                      " value is not one direct canonical " +
                      std::string(aggregate_count_window
                                      ? "engine-bound"
                                      : profile.result_type_name) +
                      " column "
                      "with an exact distinct result descriptor";
      return result;
    }
    result.navigation_value_column = static_cast<std::size_t>(
        std::distance(previous_logical.output_descriptor_ids.begin(),
                      value_column));
    if (nth_value_window) {
      const auto position_expression_id =
          invocations.front()->argument_expression_ids[1];
      const auto position = std::ranges::find_if(
          dag.expressions, [&](const auto& expression) {
            return expression.expression_id == position_expression_id;
          });
      const auto position_descriptor = std::ranges::find_if(
          dag.descriptors, [&](const auto& descriptor) {
            return position != dag.expressions.end() &&
                   descriptor.descriptor_id == position->result_descriptor_id;
          });
      if (position == dag.expressions.end() ||
          position->expression_kind !=
              api::RelationalExpressionKind::kLiteral ||
          !position->child_expression_ids.empty() ||
          position->bound_name_uuid.has_value() ||
          position->function_uuid.has_value() ||
          position->literal_kind != api::RelationalLiteralKind::kNumeric ||
          position->operator_name.has_value() ||
          !position->literal_or_parameter_ref.has_value() ||
          position_descriptor == dag.descriptors.end() ||
          typed_order_expression == dag.expressions.end() ||
          typed_order_expression->expression_kind !=
              api::RelationalExpressionKind::kIdentifier ||
          typed_order_descriptor == dag.descriptors.end() ||
          typed_order_descriptor->type_uuid != order_type_uuid ||
          position_descriptor->descriptor_id ==
              argument_descriptor->descriptor_id ||
          position_descriptor->descriptor_id ==
              result_descriptor->descriptor_id ||
          position_descriptor->descriptor_id ==
              typed_order_descriptor->descriptor_id ||
          position_descriptor->descriptor_uuid ==
              argument_descriptor->descriptor_uuid ||
          position_descriptor->descriptor_uuid ==
              result_descriptor->descriptor_uuid ||
          position_descriptor->descriptor_uuid ==
              typed_order_descriptor->descriptor_uuid ||
          position_descriptor->descriptor_uuid == profile.function_uuid ||
          position_descriptor->descriptor_uuid ==
              prepared_sort.ordering_property_uuid ||
          position_descriptor->descriptor_uuid == *window_property_uuid ||
          position_descriptor->type_uuid != order_type_uuid ||
          position_descriptor->nullability !=
              api::RelationalNullability::kNonNull ||
          position_descriptor->collation_uuid.has_value() ||
          position_descriptor->timezone_profile_id.has_value() ||
          position_descriptor->width.has_value() ||
          position_descriptor->precision.has_value() ||
          position_descriptor->scale.has_value()) {
        result.detail = std::string(family_label) +
                        " NTH_VALUE position is not one independent "
                        "non-NULL canonical int64 literal";
        return result;
      }
      CanonicalRelationalExpressionRuntime runtime(dag);
      api::EngineTypedValue operand;
      std::string operand_detail;
      if (!runtime.EvaluateForConsumer(
              position_expression_id, "int64",
              api::EngineCanonicalExpressionConsumer::window, &operand,
              &operand_detail) ||
          operand.state != api::EngineValueState::value || operand.is_null ||
          !operand.binary_value.empty() ||
          operand.descriptor.canonical_type_name != "int64" ||
          !api::QowCanonicalDescriptorIdentityV1(operand.descriptor) ||
          operand.descriptor.descriptor_uuid.canonical !=
              position_descriptor->descriptor_uuid) {
        result.detail = std::string(family_label) +
                        " NTH_VALUE position materialization failed";
        if (!operand_detail.empty()) result.detail += ": " + operand_detail;
        return result;
      }
      const auto decoded = exec::DecodeInt64Value(operand);
      if (!decoded.ok() || decoded.value <= 0) {
        result.detail = std::string(family_label) +
                        " NTH_VALUE position must be positive int64";
        return result;
      }
      result.nth_value_position_operand = std::move(operand);
    }
  }

  if (aggregate_window) {
    const auto order_expression_id =
        definitions.front()->ordering_terms.front().expression_id;
    const auto order_expression = std::ranges::find_if(
        dag.expressions, [&](const auto& expression) {
          return expression.expression_id == order_expression_id;
        });
    const auto order_descriptor = std::ranges::find_if(
        dag.descriptors, [&](const auto& descriptor) {
          return order_expression != dag.expressions.end() &&
                 descriptor.descriptor_id ==
                     order_expression->result_descriptor_id;
        });
    const bool exact_bounded_signed_order =
        order_descriptor != dag.descriptors.end() &&
        std::ranges::find(bounded_signed_type_uuids,
                          order_descriptor->type_uuid) !=
            bounded_signed_type_uuids.end();
    if (prepared_sort.order_terms.size() != 1 ||
        order_expression == dag.expressions.end() ||
        order_expression->expression_kind !=
            api::RelationalExpressionKind::kIdentifier ||
        !order_expression->child_expression_ids.empty() ||
        !order_expression->bound_name_uuid.has_value() ||
        order_expression->function_uuid.has_value() ||
        order_expression->literal_kind.has_value() ||
        order_expression->literal_or_parameter_ref.has_value() ||
        order_expression->operator_name.has_value() ||
        order_descriptor == dag.descriptors.end() ||
        !exact_bounded_signed_order ||
        order_descriptor->collation_uuid.has_value() ||
        order_descriptor->timezone_profile_id.has_value() ||
        order_descriptor->width.has_value() ||
        order_descriptor->precision.has_value() ||
        order_descriptor->scale.has_value() ||
        std::ranges::find(previous_logical.output_descriptor_ids,
                          order_descriptor->descriptor_id) ==
            previous_logical.output_descriptor_ids.end()) {
      result.detail = std::string(family_label) +
                      " " + std::string(profile.display_name) +
                      " order key is not one direct canonical bounded-signed "
                      "column";
      return result;
    }
  }

  result.ok = true;
  result.invocation = invocations.front();
  result.function = &*function;
  result.result_descriptor = &*result_descriptor;
  result.aggregate_count_star = aggregate_count_star_window;
  result.window_property_uuid = *window_property_uuid;
  result.window_frame_descriptor_uuid =
      window_property->window_frame_descriptor_uuid;
  return result;
}

PreparedGlobalRowNumberWindowBinding PrepareGlobalRowNumberWindowBinding(
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalPropertyCatalog& logical_properties,
    const api::RelationalDagNode& consumer,
    const plan::CanonicalLogicalRelationalNode& logical_consumer,
    const plan::CanonicalLogicalRelationalNode& previous_logical,
    const PreparedSortRoot& prepared_sort,
    const std::size_t materialized_column_count,
    const std::size_t result_binding_count,
    const std::string& int64_type_uuid,
    const std::string_view family_label,
    const bool allow_project_root = false) {
  return PrepareGlobalRankingWindowBinding(
      dag, logical_properties, consumer, logical_consumer, previous_logical,
      prepared_sort, materialized_column_count, result_binding_count,
      int64_type_uuid, int64_type_uuid, int64_type_uuid,
      std::array<std::string, 4>{}, family_label, kGlobalRowNumberProfile,
      allow_project_root);
}

bool MaterializeExpressionProjectBatch(
    const api::TypedRelationalDag& dag,
    const std::vector<PreparedProjectExpression>& expressions,
    const std::vector<exec::ExecutorColumnDescriptor>& output_columns,
    const exec::DescriptorBatch& input_batch,
    const CanonicalRelationalExpressionRuntimeServices& expression_services,
    exec::DescriptorBatch* output_batch,
    std::string* detail,
    const std::uint64_t maximum_output_bytes =
        std::numeric_limits<std::uint64_t>::max(),
    std::uint64_t* actual_output_bytes = nullptr,
    bool* resource_refused = nullptr) {
  if (actual_output_bytes != nullptr) *actual_output_bytes = 0;
  if (resource_refused != nullptr) *resource_refused = false;
  if (output_batch == nullptr || detail == nullptr || expressions.empty() ||
      expressions.size() != output_columns.size()) {
    if (detail != nullptr) {
      *detail = "expression PROJECT materialization request is incomplete";
    }
    return false;
  }
  *output_batch = {};
  detail->clear();
  std::uint64_t materialized_bytes = 1;
  if (materialized_bytes > maximum_output_bytes) {
    *detail = "expression PROJECT output exceeds its materialization ceiling";
    if (resource_refused != nullptr) *resource_refused = true;
    return false;
  }
  output_batch->columns = output_columns;
  output_batch->rows.reserve(input_batch.rows.size());
  CanonicalRelationalExpressionRuntime runtime(dag, expression_services);
  for (const auto& input_row : input_batch.rows) {
    exec::DescriptorTuple output_row;
    output_row.values.reserve(expressions.size());
    for (const auto& expression : expressions) {
      api::EngineTypedValue value;
      if (!runtime.EvaluateForConsumer(
              expression.expression_id, expression.expected_type,
              expression.row_binding, input_row.values,
              api::EngineCanonicalExpressionConsumer::projection, &value,
              detail)) {
        *output_batch = {};
        return false;
      }
      std::uint64_t value_bytes = 0;
      if (!CheckedAdd(value.encoded_value.size(), value.binary_value.size(),
                      &value_bytes) ||
          !CheckedAdd(materialized_bytes, value_bytes,
                      &materialized_bytes) ||
          materialized_bytes > maximum_output_bytes) {
        *detail =
            "expression PROJECT value exceeds its materialization ceiling";
        *output_batch = {};
        if (resource_refused != nullptr) *resource_refused = true;
        return false;
      }
      output_row.values.push_back(std::move(value));
    }
    output_batch->rows.push_back(std::move(output_row));
  }
  std::vector<std::uint32_t> descriptor_ids;
  descriptor_ids.reserve(output_columns.size());
  for (const auto& column : output_columns) {
    descriptor_ids.push_back(column.descriptor_id);
  }
  const auto canonical =
      exec::ValidateCanonicalDescriptorBatch(*output_batch, descriptor_ids);
  const auto values = exec::ValidateDescriptorBatch(*output_batch);
  if (!canonical.ok || !values.ok) {
    *detail = !canonical.ok
                  ? canonical.diagnostic_code + ":" + canonical.detail
                  : values.diagnostic_code + ":" + values.detail;
    *output_batch = {};
    return false;
  }
  if (actual_output_bytes != nullptr) {
    *actual_output_bytes = materialized_bytes;
  }
  return true;
}

PreparedProjectRoot PrepareExpressionProjectRoot(
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalRelationalNode& root,
    const plan::CanonicalLogicalRelationalNode& input_node,
    const MaterializedValues& input,
    const CanonicalRelationalExpressionRuntimeServices& expression_services) {
  PreparedProjectRoot result;
  if (root.output_descriptor_ids.empty() ||
      root.bound_expression_ids.size() != root.output_descriptor_ids.size() ||
      input.result_bindings.size() != input.batch.columns.size() ||
      input_node.output_descriptor_ids.size() != input.batch.columns.size()) {
    result.detail =
        "expression PROJECT input, output, or expression coverage is incomplete";
    return result;
  }

  std::vector<const api::RelationalOutputRecord*> outputs;
  for (const auto& output : dag.outputs) {
    if (output.relation_node_id == root.logical_node_id) {
      outputs.push_back(&output);
    }
  }
  std::ranges::sort(outputs, {}, &api::RelationalOutputRecord::ordinal);
  if (outputs.size() != root.output_descriptor_ids.size()) {
    result.detail = "expression PROJECT root output lineage is incomplete";
    return result;
  }

  std::unordered_map<std::uint32_t, const api::RelationalTypeDescriptor*>
      descriptors;
  std::unordered_map<std::uint32_t,
                     const api::RelationalExpressionRecord*>
      expression_records;
  for (const auto& descriptor : dag.descriptors) {
    descriptors.emplace(descriptor.descriptor_id, &descriptor);
  }
  for (const auto& expression : dag.expressions) {
    expression_records.emplace(expression.expression_id, &expression);
  }

  CanonicalRelationalExpressionRuntime runtime(dag, expression_services);
  std::vector<api::EngineTypedValue> descriptor_only_input_row;
  if (input.batch.rows.empty()) {
    descriptor_only_input_row.reserve(input.batch.columns.size());
    for (const auto& column : input.batch.columns) {
      api::EngineTypedValue value;
      value.descriptor = column.descriptor;
      value.state = api::EngineValueState::value;
      value.is_null = false;
      descriptor_only_input_row.push_back(std::move(value));
    }
  }
  const auto& type_inference_row =
      input.batch.rows.empty() ? descriptor_only_input_row
                               : input.batch.rows.front().values;
  std::vector<exec::ExecutorColumnDescriptor> output_columns;
  output_columns.reserve(outputs.size());
  std::size_t published_ordinal = 0;
  for (std::size_t ordinal = 0; ordinal < outputs.size(); ++ordinal) {
    const auto expression_id = root.bound_expression_ids[ordinal];
    const auto expression = expression_records.find(expression_id);
    const auto descriptor = descriptors.find(root.output_descriptor_ids[ordinal]);
    const auto* output = outputs[ordinal];
    if (expression == expression_records.end() ||
        descriptor == descriptors.end() || output->ordinal != ordinal ||
        output->expression_id != expression_id ||
        output->descriptor_id != root.output_descriptor_ids[ordinal] ||
        expression->second->result_descriptor_id !=
            root.output_descriptor_ids[ordinal] ||
        output->output_name_utf8.empty() ||
        descriptor->second->nullability ==
            api::RelationalNullability::kUnknown) {
      result.detail =
          "expression PROJECT output expression or descriptor binding is invalid";
      return result;
    }

    PreparedProjectExpression prepared_expression;
    prepared_expression.expression_id = expression_id;
    if (!PrepareInputRowBinding(
            dag, expression_id, input_node.output_descriptor_ids,
            &prepared_expression.row_binding, &result.detail) ||
        !runtime.InferTypeForConsumer(
            expression_id, prepared_expression.row_binding,
            type_inference_row,
            api::EngineCanonicalExpressionConsumer::projection,
            &prepared_expression.expected_type, &result.detail) ||
        prepared_expression.expected_type.empty() ||
        prepared_expression.expected_type == "null") {
      if (result.detail.empty()) {
        result.detail = "expression PROJECT result type is unresolved";
      }
      return result;
    }
    const auto type_id = dt::CanonicalTypeIdFromStableName(
        prepared_expression.expected_type);
    if (type_id == dt::CanonicalTypeId::unknown ||
        (descriptor->second->collation_uuid.has_value() &&
         type_id != dt::CanonicalTypeId::character) ||
        (descriptor->second->timezone_profile_id.has_value() &&
         prepared_expression.expected_type != "timestamp")) {
      result.detail =
          "expression PROJECT descriptor metadata contradicts its result type";
      return result;
    }
    api::EngineDescriptor output_descriptor;
    if (!input.batch.rows.empty()) {
      api::EngineTypedValue first_value;
      if (!runtime.EvaluateForConsumer(
              expression_id, prepared_expression.expected_type,
              prepared_expression.row_binding,
              input.batch.rows.front().values,
              api::EngineCanonicalExpressionConsumer::projection,
              &first_value, &result.detail)) {
        return result;
      }
      output_descriptor = std::move(first_value.descriptor);
    } else {
      const auto& source = *descriptor->second;
      output_descriptor.descriptor_uuid.canonical = source.descriptor_uuid;
      output_descriptor.descriptor_kind = "scalar";
      output_descriptor.canonical_type_name =
          prepared_expression.expected_type;
      output_descriptor.encoded_descriptor =
          "type_uuid=" + source.type_uuid + ";nullability=" +
          (source.nullability == api::RelationalNullability::kNullable
               ? "nullable"
               : "non_null");
      if (source.collation_uuid.has_value()) {
        output_descriptor.encoded_descriptor +=
            ";collation_uuid=" + *source.collation_uuid;
      }
      if (source.timezone_profile_id.has_value()) {
        output_descriptor.encoded_descriptor +=
            ";timezone_profile_id=" + *source.timezone_profile_id;
      }
      if (source.width.has_value()) {
        output_descriptor.encoded_descriptor +=
            ";width=" + std::to_string(*source.width);
      }
      if (source.precision.has_value()) {
        output_descriptor.encoded_descriptor +=
            ";precision=" + std::to_string(*source.precision);
      }
      if (source.scale.has_value()) {
        output_descriptor.encoded_descriptor +=
            ";scale=" + std::to_string(*source.scale);
      }
    }
    output_columns.push_back(
        {output->output_name_utf8, std::move(output_descriptor),
         descriptor->second->nullability ==
             api::RelationalNullability::kNullable,
         descriptor->second->descriptor_id});
    result.expressions.push_back(std::move(prepared_expression));

    exec::CanonicalResultColumnBinding binding;
    binding.physical_column_ordinal = ordinal;
    binding.visible = output->visible;
    if (binding.visible) {
      binding.published_descriptor = exec::CanonicalResultColumnDescriptor{
          static_cast<std::uint32_t>(published_ordinal++),
          output->output_name_utf8,
          descriptor->second->descriptor_uuid,
          descriptor->second->type_uuid,
          ResultNullability(descriptor->second->nullability),
          descriptor->second->collation_uuid,
          descriptor->second->timezone_profile_id};
    }
    result.result_bindings.push_back(std::move(binding));
  }

  if (!MaterializeExpressionProjectBatch(
          dag, result.expressions, output_columns, input.batch,
          expression_services, &result.expression_output_batch,
          &result.detail)) {
    result.expressions.clear();
    result.result_bindings.clear();
    return result;
  }
  result.expression_projection = true;
  result.ok = true;
  return result;
}

PreparedFilterRoot PrepareFilterRoot(
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalRelationalNode& root,
    const plan::CanonicalLogicalRelationalNode& input_node,
    const MaterializedValues& input) {
  PreparedFilterRoot result;
  if (root.output_descriptor_ids.empty() ||
      root.output_descriptor_ids != input_node.output_descriptor_ids ||
      input.result_bindings.size() != input.batch.columns.size()) {
    result.detail = "filter output does not preserve its bound input schema";
    return result;
  }
  if (std::ranges::any_of(dag.outputs, [&](const auto& output) {
        return output.relation_node_id == root.logical_node_id;
      })) {
    result.detail = "filter root output lineage is not admitted by this profile";
    return result;
  }
  if (root.bound_expression_ids.size() != 1) {
    result.detail = "filter predicate root identity is not exact";
    return result;
  }
  result.predicate_expression_id = root.bound_expression_ids.front();
  if (!PrepareInputRowBinding(
          dag, result.predicate_expression_id,
          input_node.output_descriptor_ids, &result.predicate_row_binding,
          &result.detail)) {
    return result;
  }
  result.result_bindings = input.result_bindings;
  result.ok = true;
  return result;
}

bool ExactCanonicalBooleanJoinAliasDescriptorV1(
    const api::RelationalTypeDescriptor& descriptor) {
  if (!descriptor.datatype_identity_authoritative ||
      (descriptor.nullability != api::RelationalNullability::kNonNull &&
       descriptor.nullability != api::RelationalNullability::kNullable) ||
      descriptor.descriptor_uuid != descriptor.type_uuid ||
      !CanonicalUuidText(descriptor.statement_receipt_uuid)) {
    return false;
  }
  const auto identity = dt::LookupCanonicalBooleanTypeCodecIdentityV1(
      descriptor.datatype_catalog_snapshot_uuid,
      descriptor.datatype_catalog_generation,
      descriptor.datatype_registry_generation);
  return identity.ok &&
         descriptor.descriptor_uuid == identity.row.descriptor_uuid &&
         descriptor.descriptor_generation ==
             identity.row.descriptor_generation &&
         descriptor.type_uuid == identity.row.type_uuid &&
         descriptor.type_generation == identity.row.type_generation &&
         descriptor.codec_id == identity.row.codec_id &&
         descriptor.codec_version == identity.row.codec_version &&
         descriptor.codec_generation == identity.row.codec_generation &&
         dt::IsExactCanonicalBooleanDescriptorTypeAliasV1(
             descriptor.descriptor_uuid, descriptor.descriptor_generation,
             descriptor.type_uuid, descriptor.type_generation,
             descriptor.codec_id, descriptor.codec_version,
             descriptor.codec_generation, true);
}

std::string ExactCanonicalBooleanJoinAliasRuntimeCarrierV1(
    const api::RelationalTypeDescriptor& descriptor,
    const bool nullable) {
  if (!ExactCanonicalBooleanJoinAliasDescriptorV1(descriptor) ||
      nullable != (descriptor.nullability ==
                   api::RelationalNullability::kNullable)) {
    return {};
  }
  return "datatype_descriptor_uuid=" + descriptor.descriptor_uuid +
         ";datatype_descriptor_generation=" +
         std::to_string(descriptor.descriptor_generation) +
         ";type_uuid=" + descriptor.type_uuid + ";type_generation=" +
         std::to_string(descriptor.type_generation) + ";codec_id=" +
         descriptor.codec_id + ";codec_version=" +
         std::to_string(descriptor.codec_version) + ";codec_generation=" +
         std::to_string(descriptor.codec_generation) +
         ";null_encoding=1;nullability=" +
         (nullable ? "nullable" : "non_null");
}

bool ProjectCanonicalBooleanJoinAliasRuntimeCarriersV1(
    const std::unordered_map<std::uint32_t,
                             const api::RelationalTypeDescriptor*>&
        descriptors,
    exec::DescriptorBatch* batch,
    std::string* detail) {
  if (batch == nullptr || detail == nullptr) return false;
  for (std::size_t ordinal = 0; ordinal < batch->columns.size(); ++ordinal) {
    auto& column = batch->columns[ordinal];
    const auto descriptor = descriptors.find(column.descriptor_id);
    if (descriptor == descriptors.end()) {
      *detail = "join input descriptor identity is unresolved";
      return false;
    }
    if (descriptor->second->descriptor_uuid != descriptor->second->type_uuid) {
      continue;
    }
    // The relational DAG tuple was validated against the live datatype
    // registry above. This projection closes the executor-only carrier; it
    // does not infer authority from the persisted descriptor text.
    if (!ExactCanonicalBooleanJoinAliasDescriptorV1(*descriptor->second) ||
        column.descriptor.descriptor_uuid.canonical !=
            descriptor->second->descriptor_uuid ||
        column.descriptor.descriptor_kind != "scalar" ||
        column.descriptor.canonical_type_name != "boolean" ||
        column.nullable !=
            (descriptor->second->nullability ==
             api::RelationalNullability::kNullable)) {
      *detail =
          "join descriptor and type identity domains are not independent";
      return false;
    }
    const auto encoded = ExactCanonicalBooleanJoinAliasRuntimeCarrierV1(
        *descriptor->second, column.nullable);
    if (encoded.empty()) {
      *detail = "join canonical boolean alias carrier is unresolved";
      return false;
    }
    for (auto& row : batch->rows) {
      if (ordinal >= row.values.size() ||
          row.values[ordinal].descriptor.descriptor_uuid.canonical !=
              column.descriptor.descriptor_uuid.canonical ||
          row.values[ordinal].descriptor.descriptor_kind !=
              column.descriptor.descriptor_kind ||
          row.values[ordinal].descriptor.canonical_type_name !=
              column.descriptor.canonical_type_name ||
          row.values[ordinal].descriptor.encoded_descriptor !=
              column.descriptor.encoded_descriptor) {
        *detail = "join canonical boolean row carrier differs from its column";
        return false;
      }
      row.values[ordinal].descriptor.encoded_descriptor = encoded;
    }
    column.descriptor.encoded_descriptor = encoded;
  }
  return true;
}

PreparedJoinRoot PrepareJoinRoot(
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalRelationalNode& root,
    const plan::CanonicalLogicalRelationalNode& left_node,
    const plan::CanonicalLogicalRelationalNode& right_node,
    MaterializedValues& left,
    MaterializedValues& right,
    const exec::CanonicalAcceptedJoinKind join_kind) {
  PreparedJoinRoot result;
  std::vector<std::uint32_t> predicate_descriptors =
      left_node.output_descriptor_ids;
  predicate_descriptors.insert(predicate_descriptors.end(),
                               right_node.output_descriptor_ids.begin(),
                               right_node.output_descriptor_ids.end());
  std::vector<std::uint32_t> expected_descriptors =
      left_node.output_descriptor_ids;
  const bool left_only =
      join_kind == exec::CanonicalAcceptedJoinKind::kLeftSemi ||
      join_kind == exec::CanonicalAcceptedJoinKind::kLeftAnti;
  if (!left_only) {
    expected_descriptors.insert(expected_descriptors.end(),
                                right_node.output_descriptor_ids.begin(),
                                right_node.output_descriptor_ids.end());
  }
  if (root.output_descriptor_ids.empty() ||
      root.output_descriptor_ids != expected_descriptors ||
      left.result_bindings.size() != left.batch.columns.size() ||
      right.result_bindings.size() != right.batch.columns.size()) {
    result.detail = "join output does not preserve its accepted bound shape";
    return result;
  }
  if (std::ranges::any_of(dag.outputs, [&](const auto& output) {
        return output.relation_node_id == root.logical_node_id;
      })) {
    result.detail = "join root output lineage is not admitted by this profile";
    return result;
  }
  std::unordered_map<std::uint32_t, const api::RelationalTypeDescriptor*>
      descriptors;
  for (const auto& descriptor : dag.descriptors) {
    descriptors.emplace(descriptor.descriptor_id, &descriptor);
  }
  std::unordered_set<std::string_view> join_descriptor_uuids;
  std::unordered_set<std::string_view> join_type_uuids;
  for (const auto descriptor_id : predicate_descriptors) {
    const auto descriptor = descriptors.find(descriptor_id);
    if (descriptor == descriptors.end() ||
        descriptor->second->descriptor_uuid.empty() ||
        descriptor->second->type_uuid.empty()) {
      result.detail = "join input descriptor or type identity is unresolved";
      return result;
    }
    join_descriptor_uuids.insert(descriptor->second->descriptor_uuid);
    join_type_uuids.insert(descriptor->second->type_uuid);
  }
  if (std::ranges::any_of(join_descriptor_uuids,
                          [&](const auto descriptor_uuid) {
                            if (!join_type_uuids.contains(descriptor_uuid)) {
                              return false;
                            }
                            return std::ranges::any_of(
                                predicate_descriptors,
                                [&](const auto descriptor_id) {
                                  const auto descriptor =
                                      descriptors.find(descriptor_id);
                                  return descriptor == descriptors.end() ||
                                         ((descriptor->second
                                                   ->descriptor_uuid ==
                                               descriptor_uuid ||
                                           descriptor->second->type_uuid ==
                                               descriptor_uuid) &&
                                          !ExactCanonicalBooleanJoinAliasDescriptorV1(
                                              *descriptor->second));
                                });
                          })) {
    result.detail =
        "join descriptor and type identity domains are not independent";
    return result;
  }
  if (!ProjectCanonicalBooleanJoinAliasRuntimeCarriersV1(
          descriptors, &left.batch, &result.detail) ||
      !ProjectCanonicalBooleanJoinAliasRuntimeCarriersV1(
          descriptors, &right.batch, &result.detail)) {
    return result;
  }
  const bool left_null_extended =
      join_kind == exec::CanonicalAcceptedJoinKind::kRightOuter ||
      join_kind == exec::CanonicalAcceptedJoinKind::kFullOuter;
  const bool right_null_extended =
      join_kind == exec::CanonicalAcceptedJoinKind::kLeftOuter ||
      join_kind == exec::CanonicalAcceptedJoinKind::kFullOuter;
  if ((left_null_extended &&
       std::ranges::any_of(left.batch.columns,
                           [](const auto& column) {
                             return !column.nullable;
                           })) ||
      (right_null_extended &&
       std::ranges::any_of(right.batch.columns,
                           [](const auto& column) {
                             return !column.nullable;
                           }))) {
    result.detail =
        "outer join result lacks an exact nullable descriptor carrier";
    return result;
  }

  if (join_kind != exec::CanonicalAcceptedJoinKind::kCross) {
    if (root.bound_expression_ids.size() != 1) {
      result.detail = "join predicate root identity is not exact";
      return result;
    }
    result.predicate_expression_id = root.bound_expression_ids.front();
    if (!PrepareInputRowBinding(
            dag, result.predicate_expression_id, predicate_descriptors,
            &result.predicate_row_binding, &result.detail)) {
      if (result.detail ==
          "row expression input descriptor identity is ambiguous") {
        result.detail = "join predicate input descriptor identity is ambiguous";
      } else if (result.detail ==
                 "row expression identifier is not supplied by its input") {
        result.detail =
            "join predicate identifier is not supplied by either input";
      } else if (result.detail ==
                 "row expression has a dangling expression child") {
        result.detail = "join predicate has a dangling expression child";
      }
      return result;
    }
  }

  std::size_t published_ordinal = 0;
  const auto append_bindings =
      [&](const std::vector<exec::CanonicalResultColumnBinding>& bindings,
          const std::size_t physical_base,
          const bool force_nullable) {
    for (const auto& source : bindings) {
      auto binding = source;
      binding.physical_column_ordinal += physical_base;
      if (binding.visible) {
        if (!binding.published_descriptor.has_value()) return false;
        binding.published_descriptor->ordinal =
            static_cast<std::uint32_t>(published_ordinal++);
        if (force_nullable) {
          binding.published_descriptor->nullability =
              exec::CanonicalResultNullability::kNullable;
        }
      }
      result.result_bindings.push_back(std::move(binding));
    }
    return true;
  };
  if (!append_bindings(left.result_bindings, 0, left_null_extended) ||
      (!left_only &&
       !append_bindings(right.result_bindings, left.batch.columns.size(),
                        right_null_extended))) {
    result.result_bindings.clear();
    result.detail = "join visible result binding is incomplete";
    return result;
  }
  result.ok = true;
  return result;
}

LiveSetOperationProfile MatchLiveSetOperationProfile(
    const std::string_view semantic_variant_id) {
  LiveSetOperationProfile profile;
  constexpr std::string_view kPrefix = "set-operation.";
  constexpr std::string_view kSuffix = ".v1";
  if (!semantic_variant_id.starts_with(kPrefix) ||
      !semantic_variant_id.ends_with(kSuffix) ||
      semantic_variant_id.size() <= kPrefix.size() + kSuffix.size()) {
    return profile;
  }
  const auto payload = semantic_variant_id.substr(
      kPrefix.size(),
      semantic_variant_id.size() - kPrefix.size() - kSuffix.size());
  const auto first_modifier = payload.find('.');
  const auto base = payload.substr(0, first_modifier);
  std::string operation_component;
  std::string quantifier_component;
  if (base == "union-all") {
    profile.operation = exec::CanonicalSetOperationKind::kUnion;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kAll;
    operation_component = "union";
    quantifier_component = "all";
    profile.operation_name = "UNION ALL";
  } else if (base == "union-distinct") {
    profile.operation = exec::CanonicalSetOperationKind::kUnion;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kDistinct;
    operation_component = "union";
    quantifier_component = "distinct";
    profile.operation_name = "UNION DISTINCT";
  } else if (base == "intersect-all") {
    profile.operation = exec::CanonicalSetOperationKind::kIntersect;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kAll;
    operation_component = "intersect";
    quantifier_component = "all";
    profile.operation_name = "INTERSECT ALL";
  } else if (base == "intersect-distinct") {
    profile.operation = exec::CanonicalSetOperationKind::kIntersect;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kDistinct;
    operation_component = "intersect";
    quantifier_component = "distinct";
    profile.operation_name = "INTERSECT DISTINCT";
  } else if (base == "except-all") {
    profile.operation = exec::CanonicalSetOperationKind::kExcept;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kAll;
    operation_component = "except";
    quantifier_component = "all";
    profile.operation_name = "EXCEPT ALL";
  } else if (base == "except-distinct") {
    profile.operation = exec::CanonicalSetOperationKind::kExcept;
    profile.quantifier = exec::CanonicalSetOperationQuantifier::kDistinct;
    operation_component = "except";
    quantifier_component = "distinct";
    profile.operation_name = "EXCEPT DISTINCT";
  } else {
    return profile;
  }

  bool by_name = false;
  bool type_reconciled = false;
  bool null_collation = false;
  std::size_t modifier_begin = first_modifier;
  while (modifier_begin != std::string_view::npos) {
    ++modifier_begin;
    const auto modifier_end = payload.find('.', modifier_begin);
    const auto modifier = payload.substr(
        modifier_begin,
        modifier_end == std::string_view::npos
            ? std::string_view::npos
            : modifier_end - modifier_begin);
    if (modifier == "by-name" && !by_name && !type_reconciled &&
        !null_collation) {
      by_name = true;
    } else if (modifier == "type-reconciled" && !type_reconciled &&
               !null_collation) {
      type_reconciled = true;
    } else if (modifier == "null-collation" && !null_collation) {
      null_collation = true;
    } else {
      return {};
    }
    modifier_begin = modifier_end;
  }

  profile.alignment =
      by_name ? exec::CanonicalSetOperationAlignment::kByName
              : exec::CanonicalSetOperationAlignment::kOrdinal;
  profile.type_profile =
      type_reconciled
          ? exec::CanonicalSetOperationTypeProfile::kLosslessImplicit
          : exec::CanonicalSetOperationTypeProfile::kExact;
  profile.equality_profile =
      null_collation
          ? exec::CanonicalSetOperationEqualityProfile::kNullEqualBoundCollation
          : exec::CanonicalSetOperationEqualityProfile::kExactTyped;
  profile.implementation_id = "setop." + operation_component + "-" +
                              quantifier_component + "." +
                              (by_name ? "by-name" : "ordinal");
  if (type_reconciled) {
    profile.implementation_id += ".type-reconciled";
  }
  if (null_collation) {
    profile.implementation_id += ".null-collation";
  }
  profile.implementation_id += ".typed.v1";
  profile.identity_component = operation_component + "-" +
                               quantifier_component +
                               (by_name ? ".by-name" : ".ordinal") +
                               (type_reconciled ? ".type-reconciled" : "") +
                               (null_collation ? ".null-collation" : "");
  profile.physical_semantic_id =
      "canonical.setop." + profile.identity_component + ".v1";
  if (by_name) profile.operation_name += " BY NAME";
  profile.matched = true;
  return profile;
}

PreparedSetOperationRoot PrepareSetOperationRoot(
    const api::EngineRequestContext& context,
    const api::TypedRelationalDag& dag,
    const plan::CanonicalLogicalRelationalNode& root,
    const MaterializedValues& left,
    const MaterializedValues& right,
    const LiveSetOperationProfile& profile) {
  PreparedSetOperationRoot result;
  if (!profile.matched || root.output_descriptor_ids.empty() ||
      left.batch.columns.size() != root.output_descriptor_ids.size() ||
      right.batch.columns.size() != root.output_descriptor_ids.size() ||
      left.result_bindings.size() != root.output_descriptor_ids.size() ||
      right.result_bindings.size() != root.output_descriptor_ids.size()) {
    result.detail = "set-operation input/result arity is inconsistent";
    return result;
  }
  if (std::ranges::any_of(dag.outputs, [&](const auto& output) {
        return output.relation_node_id == root.logical_node_id;
      })) {
    result.detail =
        "set-operation root output lineage is not admitted by this profile";
    return result;
  }

  std::unordered_map<std::uint32_t, const api::RelationalTypeDescriptor*>
      descriptors;
  for (const auto& descriptor : dag.descriptors) {
    descriptors.emplace(descriptor.descriptor_id, &descriptor);
  }
  std::unordered_set<std::string_view> set_operation_type_uuids;
  const auto collect_type_uuid = [&](const std::uint32_t descriptor_id) {
    const auto descriptor = descriptors.find(descriptor_id);
    if (descriptor == descriptors.end() ||
        descriptor->second->type_uuid.empty()) {
      return false;
    }
    set_operation_type_uuids.insert(descriptor->second->type_uuid);
    return true;
  };
  for (const auto descriptor_id : root.output_descriptor_ids) {
    if (!collect_type_uuid(descriptor_id)) {
      result.detail = "set-operation result type identity is unresolved";
      return result;
    }
  }
  for (const auto& column : left.batch.columns) {
    if (!collect_type_uuid(column.descriptor_id)) {
      result.detail = "set-operation left type identity is unresolved";
      return result;
    }
  }
  for (const auto& column : right.batch.columns) {
    if (!collect_type_uuid(column.descriptor_id)) {
      result.detail = "set-operation right type identity is unresolved";
      return result;
    }
  }

  std::unordered_map<std::string, std::size_t> right_name_ordinals;
  if (profile.alignment == exec::CanonicalSetOperationAlignment::kByName) {
    std::unordered_set<std::string> left_names;
    for (const auto& column : left.batch.columns) {
      if (column.stable_name.empty() ||
          !left_names.insert(column.stable_name).second) {
        result.detail = "set-operation BY NAME left names are not unique";
        return result;
      }
    }
    for (std::size_t column = 0; column < right.batch.columns.size();
         ++column) {
      if (right.batch.columns[column].stable_name.empty() ||
          !right_name_ordinals
               .emplace(right.batch.columns[column].stable_name, column)
               .second) {
        result.detail = "set-operation BY NAME right names are not unique";
        return result;
      }
    }
    if (left_names.size() != right_name_ordinals.size()) {
      result.detail = "set-operation BY NAME column sets differ";
      return result;
    }
  }

  const auto descriptor_has_type_uuid = [](const api::EngineDescriptor& value,
                                           const std::string_view type_uuid) {
    const auto token = "type_uuid=" + std::string(type_uuid);
    return value.encoded_descriptor == token ||
           value.encoded_descriptor.starts_with(token + ";");
  };
  std::size_t published_ordinal = 0;
  for (std::size_t column = 0; column < root.output_descriptor_ids.size();
       ++column) {
    const auto descriptor = descriptors.find(root.output_descriptor_ids[column]);
    const auto& left_column = left.batch.columns[column];
    std::size_t right_column_ordinal = column;
    if (profile.alignment == exec::CanonicalSetOperationAlignment::kByName) {
      const auto right_ordinal =
          right_name_ordinals.find(left_column.stable_name);
      if (right_ordinal == right_name_ordinals.end()) {
        result.detail = "set-operation BY NAME column sets differ";
        return result;
      }
      right_column_ordinal = right_ordinal->second;
    }
    const auto& right_column = right.batch.columns[right_column_ordinal];
    if (descriptor == descriptors.end() ||
        set_operation_type_uuids.contains(
            descriptor->second->descriptor_uuid) ||
        descriptor->second->nullability ==
            api::RelationalNullability::kUnknown ||
        left_column.descriptor.canonical_type_name.empty() ||
        right_column.descriptor.canonical_type_name.empty()) {
      result.detail = "set-operation descriptor reconciliation is unresolved";
      return result;
    }

    std::string result_type_name;
    if (descriptor_has_type_uuid(left_column.descriptor,
                                 descriptor->second->type_uuid)) {
      result_type_name = left_column.descriptor.canonical_type_name;
    } else if (descriptor_has_type_uuid(right_column.descriptor,
                                        descriptor->second->type_uuid)) {
      result_type_name = right_column.descriptor.canonical_type_name;
    } else if (left_column.descriptor.canonical_type_name ==
               right_column.descriptor.canonical_type_name) {
      result_type_name = left_column.descriptor.canonical_type_name;
    } else {
      result.detail =
          "set-operation common result type is not bound to either input";
      return result;
    }

    api::EngineDescriptor engine_descriptor;
    engine_descriptor.descriptor_uuid.canonical =
        descriptor->second->descriptor_uuid;
    engine_descriptor.descriptor_kind = "scalar";
    engine_descriptor.canonical_type_name = result_type_name;
    engine_descriptor.encoded_descriptor =
        "type_uuid=" + descriptor->second->type_uuid + ";nullability=" +
        (descriptor->second->nullability ==
                 api::RelationalNullability::kNullable
             ? "nullable"
             : "non_null");
    if (descriptor->second->collation_uuid.has_value()) {
      engine_descriptor.encoded_descriptor +=
          ";collation_uuid=" + *descriptor->second->collation_uuid;
    }
    if (descriptor->second->timezone_profile_id.has_value()) {
      engine_descriptor.encoded_descriptor +=
          ";timezone_profile_id=" + *descriptor->second->timezone_profile_id;
    }
    if (descriptor->second->width.has_value()) {
      engine_descriptor.encoded_descriptor +=
          ";width=" + std::to_string(*descriptor->second->width);
    }
    if (descriptor->second->precision.has_value()) {
      engine_descriptor.encoded_descriptor +=
          ";precision=" + std::to_string(*descriptor->second->precision);
    }
    if (descriptor->second->scale.has_value()) {
      engine_descriptor.encoded_descriptor +=
          ";scale=" + std::to_string(*descriptor->second->scale);
    }
    const bool nullable = descriptor->second->nullability ==
                          api::RelationalNullability::kNullable;
    if (nullable != (left_column.nullable || right_column.nullable)) {
      result.detail =
          "set-operation result nullability does not cover both inputs";
      return result;
    }
    if (profile.type_profile ==
            exec::CanonicalSetOperationTypeProfile::kExact &&
        (engine_descriptor.canonical_type_name !=
             left_column.descriptor.canonical_type_name ||
         engine_descriptor.canonical_type_name !=
             right_column.descriptor.canonical_type_name ||
         engine_descriptor.encoded_descriptor !=
             left_column.descriptor.encoded_descriptor ||
         engine_descriptor.encoded_descriptor !=
             right_column.descriptor.encoded_descriptor)) {
      result.detail =
          "set-operation exact descriptors do not share one bound type";
      return result;
    }

    const bool character_result_type =
        dt::CanonicalTypeIdFromStableName(result_type_name) ==
        dt::CanonicalTypeId::character;
    if (character_result_type &&
        profile.equality_profile ==
            exec::CanonicalSetOperationEqualityProfile::kNullEqualBoundCollation) {
      if (!descriptor->second->collation_uuid.has_value()) {
        result.detail =
            "set-operation character equality lacks a bound collation";
        return result;
      }
#if defined(SCRATCHBIRD_QOW_QUERY_ROUTE_CONTRACT_ONLY)
      (void)context;
      result.detail =
          "set-operation character equality requires the production engine "
          "resource catalog";
      return result;
#else
      api::EngineUuid collation_uuid;
      collation_uuid.canonical = *descriptor->second->collation_uuid;
      const auto resolved = api::LookupEngineResourceDescriptorByUuid(
          context, collation_uuid, "collation");
      if (!resolved.ok || !resolved.resource_descriptor.present ||
          resolved.resource_descriptor.resource_uuid.canonical !=
              collation_uuid.canonical) {
        result.detail =
            "set-operation character equality lacks current engine "
            "collation authority";
        return result;
      }
      exec::CanonicalSetOperationCollationBinding binding;
      binding.result_column = column;
      binding.collation_uuid = collation_uuid.canonical;
      binding.resource_epoch =
          resolved.resource_descriptor.resource_epoch;
      binding.collation_epoch = resolved.resource_descriptor.family_epoch;
      binding.text_seed.active = true;
      binding.text_seed.seed_pack_name =
          resolved.resource_descriptor.seed_pack_name;
      binding.text_seed.seed_pack_version =
          resolved.resource_descriptor.seed_pack_version;
      binding.text_seed.charset_name =
          resolved.resource_descriptor.parent_canonical_name;
      binding.text_seed.collation_name =
          resolved.resource_descriptor.canonical_name;
      binding.text_seed.collation_case_insensitive =
          resolved.resource_descriptor.case_insensitive;
      binding.text_seed.collation_accent_insensitive =
          resolved.resource_descriptor.accent_insensitive;
      result.collation_bindings.push_back(std::move(binding));
#endif
    } else if (descriptor->second->collation_uuid.has_value() &&
               !character_result_type) {
      result.detail = "set-operation collation targets a non-character type";
      return result;
    }

    result.result_columns.push_back(
        {left_column.stable_name, engine_descriptor,
         nullable,
         descriptor->second->descriptor_id});
    auto binding = left.result_bindings[column];
    if (binding.visible) {
      binding.published_descriptor = exec::CanonicalResultColumnDescriptor{
          static_cast<std::uint32_t>(published_ordinal++),
          left_column.stable_name,
          descriptor->second->descriptor_uuid,
          descriptor->second->type_uuid,
          ResultNullability(descriptor->second->nullability),
          descriptor->second->collation_uuid,
          descriptor->second->timezone_profile_id};
    }
    result.result_bindings.push_back(std::move(binding));
  }
  result.ok = true;
  return result;
}

bool AddBatchMemoryBytes(const exec::DescriptorBatch& batch,
                         std::uint64_t* memory_bytes,
                         const exec::DescriptorCancellationProbe
                             cancellation_requested = nullptr,
                         const void* cancellation_context = nullptr,
                         bool* cancellation_observed = nullptr,
                         bool* cancellation_probe_failed = nullptr) {
  if (memory_bytes == nullptr) return false;
  if (cancellation_observed != nullptr) *cancellation_observed = false;
  if (cancellation_probe_failed != nullptr) {
    *cancellation_probe_failed = false;
  }
  const auto stopped = [&] {
    if (cancellation_requested == nullptr) return false;
    try {
      if (!cancellation_requested(cancellation_context)) return false;
      if (cancellation_observed != nullptr) *cancellation_observed = true;
      return true;
    } catch (...) {
      if (cancellation_probe_failed != nullptr) {
        *cancellation_probe_failed = true;
      }
      return true;
    }
  };
  const auto add = [&](const std::uint64_t amount) {
    return CheckedAdd(*memory_bytes, amount, memory_bytes);
  };
  const auto add_array = [&](const std::size_t count,
                             const std::size_t element_size) {
    std::uint64_t amount = 0;
    return CheckedMultiply(count, element_size, &amount) && add(amount);
  };
  const auto add_string = [&](const std::string& value) {
    return value.capacity() != std::numeric_limits<std::size_t>::max() &&
           add(static_cast<std::uint64_t>(value.capacity()) + 1);
  };
  const auto add_descriptor = [&](const api::EngineDescriptor& descriptor) {
    return add_string(descriptor.descriptor_uuid.canonical) &&
           add_string(descriptor.descriptor_kind) &&
           add_string(descriptor.canonical_type_name) &&
           add_string(descriptor.encoded_descriptor);
  };
  if (!add(sizeof(batch)) ||
      !add_array(batch.columns.capacity(),
                 sizeof(exec::ExecutorColumnDescriptor)) ||
      !add_array(batch.rows.capacity(), sizeof(exec::DescriptorTuple))) {
    return false;
  }
  for (const auto& column : batch.columns) {
    if (stopped() || !add_string(column.stable_name) ||
        !add_descriptor(column.descriptor)) {
      return false;
    }
  }
  for (const auto& row : batch.rows) {
    if (stopped() ||
        !add_array(row.values.capacity(), sizeof(api::EngineTypedValue))) {
      return false;
    }
    for (const auto& value : row.values) {
      if (stopped() || !add_descriptor(value.descriptor) ||
          !add_string(value.encoded_value) ||
          !add(static_cast<std::uint64_t>(value.binary_value.capacity()))) {
        return false;
      }
    }
  }
  return true;
}

bool BoundDescriptorBatchLiveMemoryBytes(
    const exec::DescriptorBatch& batch,
    std::uint64_t* memory_bytes) {
  if (memory_bytes == nullptr) return false;
  *memory_bytes = sizeof(batch);
  const auto add = [&](const std::uint64_t amount) {
    return CheckedAdd(*memory_bytes, amount, memory_bytes);
  };
  const auto add_array = [&](const std::size_t count,
                             const std::size_t element_size) {
    std::uint64_t allocation = 0;
    return CheckedMultiply(count, element_size, &allocation) &&
           add(allocation);
  };
  const auto add_string = [&](const std::string& value) {
    return value.capacity() != std::numeric_limits<std::uint64_t>::max() &&
           add(static_cast<std::uint64_t>(value.capacity()) + 1);
  };
  const auto add_descriptor = [&](const api::EngineDescriptor& descriptor) {
    return add_string(descriptor.descriptor_uuid.canonical) &&
           add_string(descriptor.descriptor_kind) &&
           add_string(descriptor.canonical_type_name) &&
           add_string(descriptor.encoded_descriptor);
  };
  if (!add_array(batch.columns.capacity(),
                 sizeof(exec::ExecutorColumnDescriptor)) ||
      !add_array(batch.rows.capacity(), sizeof(exec::DescriptorTuple))) {
    return false;
  }
  for (const auto& column : batch.columns) {
    if (!add_string(column.stable_name) ||
        !add_descriptor(column.descriptor)) {
      return false;
    }
  }
  for (const auto& row : batch.rows) {
    if (!add_array(row.values.capacity(), sizeof(api::EngineTypedValue))) {
      return false;
    }
    for (const auto& value : row.values) {
      if (!add_descriptor(value.descriptor) ||
          !add_string(value.encoded_value) ||
          !add(static_cast<std::uint64_t>(value.binary_value.capacity()))) {
        return false;
      }
    }
  }
  return true;
}

bool QueryDistinctAuxiliaryMemoryBytes(const std::size_t row_count,
                                       const std::size_t column_count,
                                       std::uint64_t* memory_bytes) {
  if (memory_bytes == nullptr) return false;
  std::uint64_t coverage_bytes = 0;
  std::uint64_t representative_bytes = 0;
  return CheckedMultiply(column_count, sizeof(std::uint8_t),
                         &coverage_bytes) &&
         CheckedMultiply(row_count, sizeof(std::size_t),
                         &representative_bytes) &&
         CheckedAdd(coverage_bytes, representative_bytes, memory_bytes);
}

bool QueryDistinctOutputMemoryBytes(
    const exec::DescriptorBatch& batch,
    const std::vector<exec::CanonicalDescriptorOrderTerm>& equality_terms,
    const std::size_t maximum_value_comparisons,
    std::uint64_t* memory_bytes,
    std::string* detail) {
  if (memory_bytes == nullptr || detail == nullptr ||
      equality_terms.size() != batch.columns.size() ||
      equality_terms.empty() ||
      (maximum_value_comparisons == 0 && !batch.rows.empty())) {
    return false;
  }
  *memory_bytes = 1;
  detail->clear();
  std::vector<std::size_t> representatives;
  representatives.reserve(batch.rows.size());
  std::size_t comparison_count = 0;
  for (std::size_t row = 0; row < batch.rows.size(); ++row) {
    bool duplicate = false;
    for (const auto representative : representatives) {
      bool equal = true;
      for (const auto& term : equality_terms) {
        if (comparison_count >= maximum_value_comparisons) {
          *detail = "query DISTINCT memory projection exceeded its work bound";
          return false;
        }
        ++comparison_count;
        if (term.column >= batch.columns.size() ||
            term.column >= batch.rows[row].values.size() ||
            term.column >= batch.rows[representative].values.size()) {
          *detail = "query DISTINCT memory projection is outside its schema";
          return false;
        }
        const auto compared = exec::CompareCanonicalDescriptorOrderValues(
            batch.rows[row].values[term.column],
            batch.rows[representative].values[term.column], term);
        if (!compared.diagnostic.ok) {
          *detail = compared.diagnostic.detail;
          return false;
        }
        if (compared.comparison != 0) {
          equal = false;
          break;
        }
      }
      if (equal) {
        duplicate = true;
        break;
      }
    }
    if (duplicate) continue;
    representatives.push_back(row);
    for (const auto& value : batch.rows[row].values) {
      if (value.encoded_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        *detail = "query DISTINCT output payload accounting overflowed";
        return false;
      }
      *memory_bytes += value.encoded_value.size();
      if (value.binary_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        *detail = "query DISTINCT output payload accounting overflowed";
        return false;
      }
      *memory_bytes += value.binary_value.size();
    }
  }
  return true;
}

bool AddBatchProjectionMemoryBytes(
    const exec::DescriptorBatch& batch,
    const std::vector<std::size_t>& projected_columns,
    std::uint64_t* memory_bytes) {
  if (memory_bytes == nullptr) return false;
  for (const auto& row : batch.rows) {
    for (const auto source_column : projected_columns) {
      if (source_column >= row.values.size()) return false;
      const auto& value = row.values[source_column];
      if (value.encoded_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        return false;
      }
      *memory_bytes += value.encoded_value.size();
      if (value.binary_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        return false;
      }
      *memory_bytes += value.binary_value.size();
    }
  }
  return true;
}

bool AddBatchRowRangeMemoryBytes(const exec::DescriptorBatch& batch,
                                 const std::size_t first_row,
                                 const std::size_t row_count,
                                 std::uint64_t* memory_bytes) {
  if (memory_bytes == nullptr || first_row > batch.rows.size() ||
      row_count > batch.rows.size() - first_row) {
    return false;
  }
  for (std::size_t row_index = first_row;
       row_index < first_row + row_count; ++row_index) {
    for (const auto& value : batch.rows[row_index].values) {
      if (value.encoded_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        return false;
      }
      *memory_bytes += value.encoded_value.size();
      if (value.binary_value.size() >
          std::numeric_limits<std::uint64_t>::max() - *memory_bytes) {
        return false;
      }
      *memory_bytes += value.binary_value.size();
    }
  }
  return true;
}

bool CheckedAdd(const std::uint64_t left, const std::uint64_t right,
                std::uint64_t* result) {
  if (result == nullptr ||
      right > std::numeric_limits<std::uint64_t>::max() - left) {
    return false;
  }
  *result = left + right;
  return true;
}

bool CheckedMultiply(const std::uint64_t left, const std::uint64_t right,
                     std::uint64_t* result) {
  if (result == nullptr ||
      (left != 0 && right >
                        std::numeric_limits<std::uint64_t>::max() / left)) {
    return false;
  }
  *result = left * right;
  return true;
}

bool LogicalBitVectorPayloadBytes(const std::size_t bit_count,
                                  std::uint64_t* bytes) {
  if (bytes == nullptr) return false;
  *bytes = static_cast<std::uint64_t>(bit_count / 8);
  if (bit_count % 8 != 0) {
    return CheckedAdd(*bytes, 1, bytes);
  }
  return true;
}

std::uint64_t CanonicalUnsignedDecimalWidth(std::uint64_t value) {
  std::uint64_t width = 1;
  while (value >= 10) {
    value /= 10;
    ++width;
  }
  return width;
}

struct LiveJoinPredicateScratchBound {
  bool ok = false;
  bool cancelled = false;
  std::uint64_t maximum_payload_bytes = 0;
  std::uint64_t maximum_structural_bytes = 0;
  std::string detail;
};

LiveJoinPredicateScratchBound BoundLiveJoinPredicateScratchBytes(
    const api::TypedRelationalDag& dag, const std::uint32_t root_expression_id,
    const CanonicalRelationalExpressionRowBinding& row_binding,
    const std::uint64_t pair_payload_bytes,
    const std::function<bool()>& abort_requested) {
  LiveJoinPredicateScratchBound result;
  const auto expression_for = [&](const std::uint32_t expression_id) {
    return std::ranges::find_if(dag.expressions, [&](const auto& candidate) {
      return candidate.expression_id == expression_id;
    });
  };
  const auto descriptor_for = [&](const std::uint32_t descriptor_id) {
    return std::ranges::find_if(dag.descriptors, [&](const auto& candidate) {
      return candidate.descriptor_id == descriptor_id;
    });
  };
  const auto ascii_equal = [](const std::string_view value,
                              const std::string_view uppercase) {
    if (value.size() != uppercase.size()) return false;
    for (std::size_t index = 0; index < value.size(); ++index) {
      if (static_cast<char>(std::toupper(
              static_cast<unsigned char>(value[index]))) != uppercase[index]) {
        return false;
      }
    }
    return true;
  };
  struct EvaluationBound {
    std::uint64_t output_payload_bytes = 0;
    std::uint64_t peak_scratch_bytes = 0;
  };
  std::size_t visited_expression_count = 0;
  std::size_t maximum_expression_visits = 0;
  if (dag.expressions.empty() ||
      dag.expressions.size() >
          std::numeric_limits<std::size_t>::max() / dag.expressions.size()) {
    result.detail = "join predicate expression visit bound overflowed";
    return result;
  }
  maximum_expression_visits = dag.expressions.size() * dag.expressions.size();
  const auto bound_expression = [&](auto&& self,
                                    const std::uint32_t expression_id,
                                    EvaluationBound* bound,
                                    const std::size_t depth) -> bool {
    if (abort_requested && abort_requested()) {
      result.cancelled = true;
      return false;
    }
    if (depth > dag.expressions.size() ||
        ++visited_expression_count > maximum_expression_visits) {
      result.detail =
          "join predicate expression graph is cyclic or exceeds its finite "
          "visit ceiling";
      return false;
    }
    const auto expression = expression_for(expression_id);
    if (expression == dag.expressions.end()) {
      result.detail = "join predicate references an absent expression";
      return false;
    }
    const auto& record = *expression;
    const auto descriptor = descriptor_for(record.result_descriptor_id);
    if (descriptor == dag.descriptors.end()) {
      result.detail = "join predicate result descriptor is absent";
      return false;
    }
    const auto& type = *descriptor;
    const std::uint64_t declared_extent =
        static_cast<std::uint64_t>(type.width.value_or(0)) +
        static_cast<std::uint64_t>(type.precision.value_or(0)) +
        static_cast<std::uint64_t>(type.scale.value_or(0)) + 64;
    EvaluationBound computed;
    const auto finish_leaf = [&](const std::uint64_t payload) {
      computed.output_payload_bytes = payload;
      computed.peak_scratch_bytes = payload;
      return true;
    };
    const auto finish_unary = [&](const EvaluationBound& child,
                                  const std::uint64_t output,
                                  const std::uint64_t copies) {
      std::uint64_t frame_payload = 0;
      if (!CheckedAdd(child.output_payload_bytes, output, &frame_payload) ||
          !CheckedMultiply(frame_payload, copies, &frame_payload)) {
        return false;
      }
      computed.output_payload_bytes = output;
      computed.peak_scratch_bytes =
          std::max(child.peak_scratch_bytes, frame_payload);
      return true;
    };
    const auto finish_binary = [&](const EvaluationBound& left,
                                   const EvaluationBound& right,
                                   const std::uint64_t output,
                                   const std::uint64_t copies) {
      std::uint64_t right_with_left = 0;
      std::uint64_t frame_payload = 0;
      if (!CheckedAdd(left.output_payload_bytes, right.peak_scratch_bytes,
                      &right_with_left) ||
          !CheckedAdd(left.output_payload_bytes, right.output_payload_bytes,
                      &frame_payload) ||
          !CheckedAdd(frame_payload, output, &frame_payload) ||
          !CheckedMultiply(frame_payload, copies, &frame_payload)) {
        return false;
      }
      computed.output_payload_bytes = output;
      computed.peak_scratch_bytes =
          std::max({left.peak_scratch_bytes, right_with_left, frame_payload});
      return true;
    };

    const auto materialized_slot = std::ranges::find_if(
        row_binding.slots, [&](const auto& slot) {
          return slot.expression_id == record.expression_id;
        });
    if (materialized_slot != row_binding.slots.end()) {
      const bool duplicate_slot =
          std::ranges::find_if(
              std::next(materialized_slot), row_binding.slots.end(),
              [&](const auto& slot) {
                return slot.expression_id == record.expression_id;
              }) != row_binding.slots.end();
      const bool exact_materialized_function =
          materialized_slot->slot_kind ==
              CanonicalRelationalExpressionRowSlotKind::materialized_function &&
          record.expression_kind ==
              api::RelationalExpressionKind::kFunctionCall &&
          record.function_uuid.has_value() &&
          CanonicalUuidText(*record.function_uuid) &&
          !record.bound_name_uuid.has_value() &&
          !record.literal_kind.has_value() &&
          !record.operator_name.has_value() &&
          !record.literal_or_parameter_ref.has_value();
      const bool exact_input_identifier =
          materialized_slot->slot_kind ==
              CanonicalRelationalExpressionRowSlotKind::input_identifier &&
          record.expression_kind ==
              api::RelationalExpressionKind::kIdentifier &&
          record.child_expression_ids.empty() &&
          record.bound_name_uuid.has_value() &&
          CanonicalUuidText(*record.bound_name_uuid) &&
          !record.function_uuid.has_value() &&
          !record.literal_kind.has_value() &&
          !record.operator_name.has_value() &&
          !record.literal_or_parameter_ref.has_value();
      std::uint64_t materialized_payload = 0;
      if (duplicate_slot || materialized_slot->descriptor_id !=
                                record.result_descriptor_id ||
          materialized_slot->row_ordinal >=
              row_binding.row_descriptor_ids.size() ||
          row_binding.row_descriptor_ids[materialized_slot->row_ordinal] !=
              materialized_slot->descriptor_id ||
          (!exact_materialized_function && !exact_input_identifier) ||
          !CheckedAdd(pair_payload_bytes, declared_extent,
                      &materialized_payload) ||
          !finish_leaf(materialized_payload)) {
        result.detail =
            "join predicate materialized row slot is not exactly bounded";
        return false;
      }
      *bound = computed;
      return true;
    }

    bool bounded = false;
    switch (record.expression_kind) {
      case api::RelationalExpressionKind::kLiteral: {
        if (!record.child_expression_ids.empty()) break;
        std::uint64_t literal_payload = declared_extent;
        if (record.literal_or_parameter_ref.has_value() &&
            !CheckedAdd(literal_payload,
                        record.literal_or_parameter_ref->size(),
                        &literal_payload)) {
          break;
        }
        bounded = finish_leaf(literal_payload);
        break;
      }
      case api::RelationalExpressionKind::kIdentifier: {
        if (!record.child_expression_ids.empty()) break;
        std::uint64_t identifier_payload = 0;
        bounded = CheckedAdd(pair_payload_bytes, declared_extent,
                             &identifier_payload) &&
                  finish_leaf(identifier_payload);
        break;
      }
      case api::RelationalExpressionKind::kParenthesized: {
        if (record.child_expression_ids.size() != 1) break;
        EvaluationBound child;
        std::uint64_t output = 0;
        bounded = self(self, record.child_expression_ids.front(), &child,
                       depth + 1) &&
                  CheckedAdd(child.output_payload_bytes, declared_extent,
                             &output) &&
                  finish_unary(child, output, 3);
        break;
      }
      case api::RelationalExpressionKind::kUnary: {
        const std::string_view operation =
            record.operator_name.has_value()
                ? std::string_view(*record.operator_name)
                : std::string_view{};
        if (record.child_expression_ids.size() != 1 ||
            (!ascii_equal(operation, "+") &&
             !ascii_equal(operation, "-") &&
             !ascii_equal(operation, "NOT"))) {
          break;
        }
        EvaluationBound child;
        std::uint64_t output = 0;
        bounded = self(self, record.child_expression_ids.front(), &child,
                       depth + 1) &&
                  CheckedAdd(child.output_payload_bytes, declared_extent,
                             &output) &&
                  finish_unary(child, output, 4);
        break;
      }
      case api::RelationalExpressionKind::kBinary: {
        const std::string_view operation =
            record.operator_name.has_value()
                ? std::string_view(*record.operator_name)
                : std::string_view{};
        const bool arithmetic =
            ascii_equal(operation, "+") || ascii_equal(operation, "-") ||
            ascii_equal(operation, "*") || ascii_equal(operation, "/") ||
            ascii_equal(operation, "%");
        const bool logical = ascii_equal(operation, "AND") ||
                             ascii_equal(operation, "OR") ||
                             ascii_equal(operation, "XOR");
        const bool text_concat = ascii_equal(operation, "||");
        const bool text_match = ascii_equal(operation, "LIKE") ||
                                ascii_equal(operation, "ILIKE");
        const bool comparison =
            ascii_equal(operation, "IS") || ascii_equal(operation, "=") ||
            ascii_equal(operation, "<>") || ascii_equal(operation, "!=") ||
            ascii_equal(operation, "<") || ascii_equal(operation, "<=") ||
            ascii_equal(operation, ">") || ascii_equal(operation, ">=") ||
            ascii_equal(operation, "IS DISTINCT FROM") ||
            ascii_equal(operation, "IS NOT DISTINCT FROM");
        if (record.child_expression_ids.size() != 2 ||
            (!arithmetic && !logical && !text_concat && !text_match &&
             !comparison)) {
          break;
        }
        EvaluationBound left;
        EvaluationBound right;
        std::uint64_t child_payload = 0;
        std::uint64_t output = 0;
        if (!self(self, record.child_expression_ids[0], &left, depth + 1) ||
            !self(self, record.child_expression_ids[1], &right, depth + 1) ||
            !CheckedAdd(left.output_payload_bytes,
                        right.output_payload_bytes, &child_payload)) {
          break;
        }
        if (logical || text_match || comparison) {
          bounded = CheckedAdd(8, declared_extent, &output) &&
                    finish_binary(left, right, output,
                                  text_match ? 6 : 4);
        } else {
          bounded = CheckedAdd(child_payload, declared_extent, &output) &&
                    finish_binary(left, right, output, 4);
        }
        break;
      }
      case api::RelationalExpressionKind::kFunctionCall: {
        // POINT is the sole functionless built-in in this runtime and has a
        // fixed 24-byte SBP1 result. External function callbacks have no payload
        // ceiling in this ABI and therefore remain fail-closed here.
        if (record.function_uuid.has_value() ||
            record.operator_name != "POINT" ||
            record.child_expression_ids.size() != 2) {
          break;
        }
        EvaluationBound left;
        EvaluationBound right;
        std::uint64_t output = 0;
        bounded = self(self, record.child_expression_ids[0], &left,
                       depth + 1) &&
                  self(self, record.child_expression_ids[1], &right,
                       depth + 1) &&
                  CheckedAdd(24, declared_extent, &output) &&
                  finish_binary(left, right, output, 4);
        break;
      }
      case api::RelationalExpressionKind::kParameter: {
        if (!record.child_expression_ids.empty() ||
            !record.parameter_typed_value_v1.has_value() ||
            record.literal_or_parameter_ref.has_value() ||
            record.literal_typed_value_v1.has_value() ||
            record.function_uuid.has_value() ||
            record.bound_name_uuid.has_value() ||
            record.literal_kind.has_value() ||
            record.operator_name.has_value()) {
          break;
        }
        const auto& typed = *record.parameter_typed_value_v1;
        const bool null_value = typed.value_state == "null";
        const bool materialized_value = typed.value_state == "value";
        if ((!null_value && !materialized_value) ||
            typed.descriptor_generation == 0 ||
            typed.descriptor_uuid != type.descriptor_uuid ||
            (null_value && !typed.canonical_value_bytes.empty()) ||
            (materialized_value &&
             typed.canonical_value_bytes.size() != 8)) {
          break;
        }
        std::uint64_t parameter_payload = declared_extent;
        std::uint64_t typed_metadata_bytes = 0;
        bounded = CheckedAdd(
                      parameter_payload,
                      static_cast<std::uint64_t>(
                          typed.canonical_value_bytes.size()),
                      &parameter_payload) &&
                  CheckedAdd(
                      static_cast<std::uint64_t>(typed.descriptor_uuid.size()),
                      static_cast<std::uint64_t>(typed.value_state.size()),
                      &typed_metadata_bytes) &&
                  CheckedAdd(typed_metadata_bytes, 2,
                             &typed_metadata_bytes) &&
                  CheckedAdd(parameter_payload, typed_metadata_bytes,
                             &parameter_payload) &&
                  finish_leaf(parameter_payload);
        break;
      }
    }
    if (!bounded) {
      if (result.detail.empty()) {
        result.detail =
            "join predicate is outside the finite payload-bounded profile "
            "or its multiplicity-aware bound overflowed";
      }
      return false;
    }
    *bound = computed;
    return true;
  };

  EvaluationBound root_bound;
  if (!bound_expression(bound_expression, root_expression_id, &root_bound,
                        1)) {
    return result;
  }
  result.maximum_payload_bytes = root_bound.peak_scratch_bytes;
  std::uint64_t structural_bytes =
      sizeof(CanonicalRelationalExpressionRuntime) +
      8 * sizeof(void*);
  std::uint64_t entry_bytes = 0;
  std::uint64_t reachable_edges = 1;
  for (const auto& expression : dag.expressions) {
    if (!CheckedAdd(reachable_edges, expression.child_expression_ids.size(),
                    &reachable_edges)) {
      result.detail = "join predicate structural edge bound overflowed";
      return result;
    }
  }
  const auto add_entries = [&](const std::uint64_t count,
                               const std::uint64_t bytes_per_entry) {
    return CheckedMultiply(count, bytes_per_entry, &entry_bytes) &&
           CheckedAdd(structural_bytes, entry_bytes, &structural_bytes);
  };
  // Conservative node-plus-bucket envelopes for the runtime descriptor,
  // expression, inferred-type, inference-stack, row-binding, reachability,
  // and pending-work containers. The row values themselves are carried by
  // pair_payload_bytes above.
  if (!add_entries(dag.expressions.size(),
                   sizeof(std::pair<const std::uint32_t,
                                    const api::RelationalExpressionRecord*>) +
                       5 * sizeof(void*)) ||
      !add_entries(dag.descriptors.size(),
                   sizeof(std::pair<const std::uint32_t,
                                    const api::RelationalTypeDescriptor*>) +
                       sizeof(std::pair<const std::uint32_t, std::string>) +
                       8 * sizeof(void*) + 129) ||
      !add_entries(dag.expressions.size(),
                   2 * sizeof(std::uint32_t) + 6 * sizeof(void*)) ||
      !add_entries(row_binding.row_descriptor_ids.size(),
                   sizeof(std::uint32_t) + 3 * sizeof(void*)) ||
      !add_entries((row_binding.row_nullable.size() + 63) / 64,
                   sizeof(std::uint64_t)) ||
      !add_entries(row_binding.slots.size(),
                   sizeof(CanonicalRelationalExpressionRowSlotBinding) +
                       sizeof(std::pair<const std::uint32_t,
                                        const api::EngineTypedValue*>) +
                       sizeof(std::pair<
                           const std::size_t,
                           CanonicalRelationalExpressionRowSlotKind>) +
                       12 * sizeof(void*)) ||
      !add_entries(reachable_edges,
                   sizeof(std::uint32_t) + sizeof(void*))) {
    result.detail = "join predicate structural memory bound overflowed";
    return result;
  }
  result.maximum_structural_bytes = structural_bytes;
  result.ok = true;
  return result;
}

std::optional<std::size_t> SelectedNodeAggregateMemoryBound(
    const exec::TypedPhysicalNodeDag& dag,
    const exec::PhysicalNodeRecord& node) {
  if (dag.memory_budget_bytes == 0 || node.memory_bytes_required == 0 ||
      node.memory_bytes_required > dag.memory_budget_bytes ||
      node.memory_bytes_required >
          static_cast<std::uint64_t>(
              std::numeric_limits<std::size_t>::max())) {
    return std::nullopt;
  }
  const auto callback_limit =
      node.dispatcher_callback_memory_limit_bytes == 0
          ? node.memory_bytes_required
          : std::min(node.memory_bytes_required,
                     node.dispatcher_callback_memory_limit_bytes);
  if (callback_limit == 0 ||
      callback_limit > std::numeric_limits<std::size_t>::max()) {
    return std::nullopt;
  }
  return static_cast<std::size_t>(callback_limit);
}

constexpr std::uint64_t kCanonicalAggregateKernelBaseMemoryBytes = 1024;

struct ExpressionSortKeyReceiptIssueResult {
  exec::DescriptorRuntimeDiagnostic diagnostic;
  std::shared_ptr<const exec::CanonicalDescriptorSortKeyReceipt> receipt;
  std::uint64_t actual_order_key_batch_bytes = 0;
};

struct FilterPredicateReceiptIssueResult {
  exec::DescriptorRuntimeDiagnostic diagnostic;
  std::shared_ptr<const exec::CanonicalDescriptorFilterPredicateReceipt>
      receipt;
};

